const matchParens = (lst) => {
  const isBalanced = (s) => {
    let balance = 0;
    for (let char of s) {
      if (char === '(') balance++;
      else balance--;
      if (balance < 0) return false;
    }
    return balance === 0;
  };

  const s1 = lst[0];
  const s2 = lst[1];

  if (isBalanced(s1 + s2) || isBalanced(s2 + s1)) {
    return 'Yes';
  }
  return 'No';
};

